// Generated by scripts/syllabus-catalogue.js from the roadmaps and tools. Don't edit by hand.
export const CATALOGUE_VERSION = "1d6q18x1td";
export const CATALOGUE = [{"id":"m:ds.arrays","title":"Arrays and searching","text":"Arrays and searching. Trace linear, binary, jump and interpolation search and count comparisons. Say when binary search applies and find its off-by-one traps. Linear, binary, jump and interpolation search, plus lower and upper bound, probe by probe."},
  {"id":"m:ds.stacks","title":"Stacks and queues","text":"Stacks and queues. Convert infix to postfix and evaluate postfix with a stack. Implement a circular queue and explain the full vs empty condition. Push, pop, circular queues and deques, bracket matching, infix to postfix and postfix evaluation."},
  {"id":"m:ds.lists","title":"Linked lists","text":"Linked lists. Insert, delete and reverse singly and doubly linked lists by hand. Compare list and array costs for each operation. Singly, doubly and circular lists: insert, delete, reverse with moving arrows, and Floyd's cycle detection."},
  {"id":"m:ds.bst","title":"Binary trees and BSTs","text":"Binary trees and BSTs. Write all four traversals of a tree. Delete from a BST in all three cases. Rebuild a tree from two traversals. Insert, delete (all three cases), search, successor and the four traversals, with nodes gliding."},
  {"id":"m:ds.avl","title":"Balanced trees (AVL)","text":"Balanced trees (AVL). Pick the right rotation (LL, RR, LR, RL) from balance factors. Bound the height of an AVL tree with n nodes. Balance factors on every node and LL, RR, LR and RL rotations animated as they happen."},
  {"id":"m:ds.heaps","title":"Heaps and priority queues","text":"Heaps and priority queues. Insert and extract on a heap stored as an array. Explain why build-heap is O(n), not O(n log n). Min and max heaps as an array and a tree at once: sift up, sift down, build-heap, decrease-key."},
  {"id":"m:ds.hashing","title":"Hash tables","text":"Hash tables. Fill a table with chaining, linear, quadratic and double hashing. Count probes and explain primary and secondary clustering. Chaining, linear, quadratic and double hashing, plus extendible hashing."},
  {"id":"m:ds.sets","title":"Tries and disjoint sets","text":"Tries and disjoint sets. Build a trie and use it for prefix search. Run union-find with union by rank and path compression. Insert, search, prefix search, autocomplete and delete on a prefix tree that grows as you type. Disjoint sets with union by rank or size and path compression, compared with naive union."},
  {"id":"m:algo.analysis","title":"Asymptotic analysis and recurrences","text":"Asymptotic analysis and recurrences. Compare growth rates with O, Ω and Θ. Solve recurrences with the recursion tree and the master theorem. Recursion trees drawn level by level, master theorem cases with the reasoning, substitution checks and growth rates compared."},
  {"id":"m:algo.sorting","title":"Sorting","text":"Sorting. Trace every classic sort and state its best, worst and average cost. Say which sorts are stable and in place. Count comparisons and swaps for a given input. Bubble, insertion, merge, quick, heap, radix and more, with pseudocode and live variables."},
  {"id":"m:algo.graphs","title":"Graph traversal","text":"Graph traversal. Run BFS and DFS and classify every edge. Find components, detect cycles and topologically sort a DAG. BFS and DFS with the queue, stack and edge types, plus components, cycles, bipartite check and topological sort. Kosaraju's two passes on G and its reverse, Tarjan's disc/low stack, and the condensation DAG."},
  {"id":"m:algo.greedy","title":"Greedy algorithms and MSTs","text":"Greedy algorithms and MSTs. Run Kruskal's and Prim's and explain the cut property. Recognise when greedy fails. Kruskal with a live union-find forest and Prim with its priority queue, edge by edge."},
  {"id":"m:algo.paths","title":"Shortest paths","text":"Shortest paths. Run Dijkstra, Bellman-Ford and Floyd-Warshall by hand. Say why Dijkstra fails with negative edges. Dijkstra, Bellman–Ford and Floyd–Warshall: every relaxation, negative cycles and the path rebuilt."},
  {"id":"m:algo.dp","title":"Dynamic programming","text":"Dynamic programming. Fill LCS, knapsack, edit distance and matrix-chain tables. Spot overlapping subproblems and write the recurrence. DP tables filled cell by cell with traceback: LCS, edit distance, knapsack, coin change, matrix chain, LIS."},
  {"id":"m:dm.logic","title":"Propositional and first-order logic","text":"Propositional and first-order logic. Check validity with truth tables and equivalences. Translate English into quantified statements. Truth tables built column by column, equivalences, CNF and DNF, rules of inference and quantifiers over a small domain."},
  {"id":"m:dm.sets","title":"Sets, relations, functions and groups","text":"Sets, relations, functions and groups. Test a relation for reflexive, symmetric, transitive and equivalence. Count functions and relations between finite sets. Draw Hasse diagrams and check for a lattice. Check group properties. A relation as a matrix and a digraph: properties, Warshall's closure, equivalence classes, Hasse diagrams and lattices."},
  {"id":"m:dm.counting","title":"Combinatorics and recurrences","text":"Combinatorics and recurrences. Use permutations, combinations, pigeonhole and inclusion-exclusion. Count derangements and Catalan structures. Solve linear recurrences. Permutations, combinations, stars and bars, inclusion-exclusion on a Venn diagram, derangements, Catalan numbers and recurrences."},
  {"id":"m:dm.graphs","title":"Graph theory","text":"Graph theory. Use degree sums, connectivity, matching and colouring results. Count edges and components from given conditions. Havel-Hakimi, Euler and Hamilton tours, bipartite checks, chromatic number, matchings, Euler's formula and spanning-tree counts."},
  {"id":"m:dl.numbers","title":"Number systems and representation","text":"Number systems and representation. Convert between bases. Work with signed magnitude, 1's and 2's complement and detect overflow. Base conversion with every division and multiplication, fractions included, plus 1's and 2's complement and overflow."},
  {"id":"m:dl.boolean","title":"Boolean algebra and K-maps","text":"Boolean algebra and K-maps. Minimise a function with a K-map, including don't-cares. Count prime and essential prime implicants. Karnaugh maps for 2 to 5 variables with don't-cares: prime implicants, essential ones, minimal SOP and POS, and Quine-McCluskey."},
  {"id":"m:dl.circuits","title":"Combinational and sequential circuits","text":"Combinational and sequential circuits. Analyse multiplexers, decoders and adders. Trace flip-flops and design counters. Multiplexers, decoders, half and full adders, ripple-carry delay and comparators, with live values on every wire. SR, JK, D and T flip-flops with timing diagrams, conversions, synchronous and ripple counters, ring and Johnson counters."},
  {"id":"m:coa.isa","title":"Instructions and addressing modes","text":"Instructions and addressing modes. Work out effective addresses for each addressing mode. Design instruction formats from opcode and operand counts. Immediate, direct, indirect, register, indexed, base, relative and auto-increment, on a small machine; plus instruction formats."},
  {"id":"m:coa.float","title":"Floating point (IEEE 754)","text":"Floating point (IEEE 754). Encode and decode single-precision numbers. Encode and decode half, single and double precision: normalise, bias, round to nearest even, denormals, ∞ and NaN."},
  {"id":"m:coa.pipeline","title":"Pipelining","text":"Pipelining. Compute speedup and throughput. Find data, control and structural hazards and the stalls they cause. A 5-stage timing diagram cycle by cycle: data hazards, forwarding, load-use stalls, branch penalties, CPI and speedup."},
  {"id":"m:coa.cache","title":"Cache and memory hierarchy","text":"Cache and memory hierarchy. Split an address into tag, index and offset for direct, set-associative and fully associative caches. Compute hit ratios and average access time. Tag, index and offset bits, then a reference trace with every hit, miss and LRU or FIFO eviction, plus average access time."},
  {"id":"m:coa.io","title":"I/O, interrupts and DMA","text":"I/O, interrupts and DMA. Compare programmed, interrupt-driven and DMA transfer and compute their overheads. Polling, interrupts and DMA compared by CPU time, worked out step by step, plus burst and cycle-stealing DMA."},
  {"id":"m:os.scheduling","title":"CPU scheduling","text":"CPU scheduling. Draw Gantt charts for FCFS, SJF, SRTF, priority and round robin. Compute waiting, turnaround and response time. FCFS, SJF, SRTF, HRRN, Priority, Round Robin, multilevel and feedback queues, with a live Gantt chart."},
  {"id":"m:os.sync","title":"Process synchronisation","text":"Process synchronisation. Spot a race condition in interleaved code. Solve producer-consumer, readers-writers and dining philosophers with semaphores. Producer–consumer, readers–writers, dining philosophers and race conditions. You pick who runs."},
  {"id":"m:os.deadlock","title":"Deadlocks","text":"Deadlocks. Run the Banker's safety and request algorithms. Detect deadlock from a resource-allocation graph or matrices. Need matrix, safety check and a timeline of resource requests: is the system safe? Draw a resource-allocation graph and watch cycles and the detection algorithm."},
  {"id":"m:os.memory","title":"Memory management and paging","text":"Memory management and paging. Place processes with first, next, best and worst fit and buddy allocation. Translate addresses with page tables and TLBs and compute effective access time. First, next, best and worst fit on a live memory bar, plus buddy-system splits and merges. Paging with a TLB, multilevel page tables and segmentation: logical to physical, bit by bit."},
  {"id":"m:os.vm","title":"Virtual memory and page replacement","text":"Virtual memory and page replacement. Count page faults for FIFO, LRU and optimal. Show Belady's anomaly with FIFO. FIFO, LRU, Optimal, LFU, MFU, the clock and NRU, frame by frame, plus working sets and Belady's anomaly."},
  {"id":"m:os.disk","title":"Disk scheduling and file systems","text":"Disk scheduling and file systems. Compute head movement for FCFS, SSTF, SCAN, C-SCAN, LOOK and C-LOOK. Size file allocation tables and inode block pointers. FCFS, SSTF, SCAN, C-SCAN, LOOK, C-LOOK, N-step SCAN and F-SCAN, with the head's path drawn out. Inode direct and indirect pointers: maximum file size, and the disk reads to reach any byte. Plus contiguous, linked and indexed allocation."},
  {"id":"m:db.er","title":"ER model to relations","text":"ER model to relations. Turn entities, weak entities and relationships into tables. Work out the minimum number of tables. Draw an ER diagram in Chen notation, then map it to tables one rule at a time, with every key shown."},
  {"id":"m:db.sql","title":"Relational algebra, SQL and joins","text":"Relational algebra, SQL and joins. Predict the output of joins, including outer, semi and anti joins and NULLs. Estimate the cost of nested-loop, block and hash joins. INNER, OUTER, SEMI and ANTI joins row by row, plus nested-loop, block nested-loop, sort-merge and hash join with I/O costs. SQL to relational algebra trees, rewritten step by step: push selections down, reorder joins, estimate sizes."},
  {"id":"m:db.normal","title":"Functional dependencies and normal forms","text":"Functional dependencies and normal forms. Find closures, candidate keys and a minimal cover. Decide the highest normal form and decompose losslessly. Closures, candidate keys, 1NF to BCNF, minimal cover and decompositions."},
  {"id":"m:db.index","title":"Indexing: B-trees, B+ trees and hashing","text":"Indexing: B-trees, B+ trees and hashing. Insert into and delete from B and B+ trees. Compute the order and height of an index from block sizes. Keys in every node: median splits, predecessor and successor swaps, borrows and merges (CLRS t). Insert, delete and search with every split, borrow and merge animated. Chaining, linear, quadratic and double hashing, plus extendible hashing."},
  {"id":"m:db.txn","title":"Transactions and concurrency control","text":"Transactions and concurrency control. Test schedules for conflict and view serialisability. Classify schedules as recoverable, cascadeless or strict. Run 2PL and timestamp ordering. Precedence graphs, conflict and view serialisability, recoverable and strict schedules. Two-phase locking with a lock table and deadlocks, timestamp ordering and validation, step by step."},
  {"id":"m:db.recovery","title":"Recovery","text":"Recovery. Replay a log with undo and redo after a crash, with checkpoints. Crash anywhere in the log, then watch redo repeat history and undo roll back the losers."},
  {"id":"m:cn.layers","title":"Layering and the OSI and TCP/IP models","text":"Layering and the OSI and TCP/IP models. Place each protocol in its layer and explain encapsulation. A message going down the stack gaining headers, through a router that opens three layers, and back up, with every byte of overhead counted."},
  {"id":"m:cn.link","title":"Data link: errors and medium access","text":"Data link: errors and medium access. Compute CRC remainders and Hamming codes. Compare ALOHA, CSMA/CD and their efficiency. CRC long division, Hamming codes that fix a flipped bit, and the Internet checksum. Pure and slotted ALOHA, CSMA/CD with binary exponential backoff, and CSMA/CA with RTS/CTS."},
  {"id":"m:cn.flow","title":"Flow control: sliding window","text":"Flow control: sliding window. Compute utilisation for stop-and-wait, Go-Back-N and Selective Repeat. Find the minimum sequence-number bits. Stop-and-Wait, Go-Back-N and Selective Repeat on a timeline, with lost frames and ACKs."},
  {"id":"m:cn.ip","title":"IP addressing, subnetting and CIDR","text":"IP addressing, subnetting and CIDR. Find network, broadcast and host ranges from a prefix. Plan VLSM and apply longest-prefix match. Fragment a datagram and fill the offsets. Network, broadcast and host range from any IPv4 address, in binary, plus a VLSM planner. Forward a packet by longest prefix match, bit by bit, and summarise routes into supernets. Split a datagram for a smaller MTU: fragment sizes, offsets and the MF flag."},
  {"id":"m:cn.routing","title":"Routing","text":"Routing. Run link-state and distance-vector routing. Explain count-to-infinity and poisoned reverse. LSP flooding, Dijkstra and distance-vector routing, with packets hopping along the chosen path."},
  {"id":"m:cn.transport","title":"Transport: TCP and congestion control","text":"Transport: TCP and congestion control. Trace the congestion window through slow start, avoidance and loss. Compute token and leaky bucket outputs. Slow start, Tahoe, Reno and CUBIC round by round, plus the three-way handshake and teardown. Leaky and token buckets filling and draining tick by tick, plus the burst-length formula."},
  {"id":"m:cn.app","title":"Application layer: DNS and HTTP","text":"Application layer: DNS and HTTP. Count RTTs for DNS lookups and persistent vs non-persistent HTTP. Iterative and recursive DNS lookups with caching, and HTTP page-load times for every connection type."},
  {"id":"m:toc.regular","title":"Finite automata","text":"Finite automata. Design DFAs and NFAs for a language. Convert NFA to DFA and minimise it. Run a DFA, NFA or ε-NFA on any string and watch the active states light up. The subset construction with ε-closures, the DFA growing one move at a time. Partition refinement: 0-, 1-, 2-equivalence until equivalent states merge."},
  {"id":"m:toc.regex","title":"Regular expressions","text":"Regular expressions. Convert between regular expressions and automata in both directions. Build product automata for intersection and difference. Thompson's construction, fragment by fragment, for any regular expression. State elimination with edge labels rerouting as states vanish, plus union and intersection of DFAs."},
  {"id":"m:toc.pumping","title":"Non-regular languages","text":"Non-regular languages. Prove a language is not regular with the pumping lemma. Use closure properties to decide regularity. Play the pumping game against an adversary: pick s, it splits xyz, you pick i. Can you prove L isn't regular?"},
  {"id":"m:toc.cfl","title":"Context-free languages and PDAs","text":"Context-free languages and PDAs. Design a PDA for a language. Convert a grammar to CNF and GNF. Check membership with CYK. Nondeterministic PDAs searched breadth first, the stack animated, and CFG → PDA. Chomsky normal form step by step (ε, unit and useless rules, binarise), then on to Greibach normal form. Fill the CYK triangle cell by cell and get the parse tree for CNF grammars."},
  {"id":"m:toc.tm","title":"Turing machines and decidability","text":"Turing machines and decidability. Trace a Turing machine. Classify problems as decidable, semi-decidable or undecidable. A live tape and head: aⁿbⁿcⁿ, palindromes, binary increment, busy beaver."},
  {"id":"m:cd.lexing","title":"Lexical analysis","text":"Lexical analysis. Count tokens in a program and explain longest match. A maximal-munch lexer DFA turns characters into tokens and fills the symbol table."},
  {"id":"m:cd.grammars","title":"Grammar clean-up, FIRST and FOLLOW","text":"Grammar clean-up, FIRST and FOLLOW. Remove left recursion and left-factor. Compute FIRST and FOLLOW sets. Remove direct and indirect left recursion, then left factor, rule by rule. Compute FIRST and FOLLOW sets pass by pass, with the reason for every symbol."},
  {"id":"m:cd.topdown","title":"Top-down parsing","text":"Top-down parsing. Build an LL(1) table and find conflicts. Predictive parsing table, conflicts, and a stack trace that grows the parse tree."},
  {"id":"m:cd.bottomup","title":"Bottom-up parsing","text":"Bottom-up parsing. Build LR(0), SLR, LALR and CLR tables and count states. Find shift-reduce and reduce-reduce conflicts. Parse with operator precedence. LR(0), SLR, LALR and CLR: item sets, tables, conflicts and bottom-up parses. LEADING and TRAILING, the ⋖ ≐ ⋗ table, precedence functions and shift-reduce parses."},
  {"id":"m:cd.sdt","title":"Syntax-directed translation","text":"Syntax-directed translation. Evaluate S- and L-attributed definitions on a parse tree. Annotated parse trees: synthesised and inherited attributes evaluated in dependency order."},
  {"id":"m:cd.ir","title":"Intermediate code and optimisation","text":"Intermediate code and optimisation. Write three-address code, quadruples and triples, and build a DAG. Apply local optimisations and liveness-based register allocation. Syntax tree to TAC, DAG with common subexpressions, quadruples and triples. Leaders, basic blocks and the flow graph, then folding, propagation, CSE and dead code, one rewrite at a time. Liveness to a fixed point, the interference graph, then Chaitin's simplify, spill and select with k registers."},
  {"id":"m:em.linear","title":"Linear algebra","text":"Linear algebra. Find rank, determinants, eigenvalues and eigenvectors. Decide when a system of equations has solutions. Gaussian elimination with exact fractions: rank, determinants, inverses, Ax = b, and eigenvalues with eigenvectors."},
  {"id":"m:em.calculus","title":"Calculus","text":"Calculus. Evaluate limits, find maxima and minima, and integrate standard forms. Limits by table and L'Hôpital, maxima and minima with a sign chart, Riemann sums closing in on an integral, and the MVT."},
  {"id":"m:em.probability","title":"Probability and statistics","text":"Probability and statistics. Use conditional probability and Bayes' theorem. Work with expectation, variance and common distributions. Sample spaces, conditional probability and Bayes with a tree, E[X] and Var(X), and binomial to normal distributions plotted."},
  {"id":"m:em.aptitude","title":"General aptitude","text":"General aptitude. Solve quantitative, verbal, analytical and spatial questions quickly. Percentages, profit, mixtures, work, speed, averages, interest, series, clocks and calendars, solved step by step, then timed sets."},
  {"id":"m:pl.trees","title":"Binary trees and BSTs","text":"Binary trees and BSTs. Write the four traversals, recursively and with a stack or queue. Find height, diameter and lowest common ancestor. Insert, delete and validate a BST. Insert, delete (all three cases), search, successor and the four traversals, with nodes gliding. Balance factors on every node and LL, RR, LR and RL rotations animated as they happen."},
  {"id":"m:pl.graphs","title":"BFS, DFS and topological sort","text":"BFS, DFS and topological sort. Choose BFS or DFS for a problem and code both on an adjacency list or a grid. Detect a cycle and order tasks with topological sort. BFS and DFS with the queue, stack and edge types, plus components, cycles, bipartite check and topological sort. Kosaraju's two passes on G and its reverse, Tarjan's disc/low stack, and the condensation DAG."},
  {"id":"m:pl.paths","title":"Shortest paths and spanning trees","text":"Shortest paths and spanning trees. Run Dijkstra with a heap and say why it fails with negative edges. Build a minimum spanning tree with Kruskal's or Prim's. Dijkstra, Bellman–Ford and Floyd–Warshall: every relaxation, negative cycles and the path rebuilt. Kruskal with a live union-find forest and Prim with its priority queue, edge by edge."},
  {"id":"m:pl.os-sync","title":"Synchronisation and deadlock","text":"Synchronisation and deadlock. Explain race conditions, mutexes and semaphores with producer-consumer. State the four deadlock conditions and how to prevent or avoid each. Producer–consumer, readers–writers, dining philosophers and race conditions. You pick who runs. Need matrix, safety check and a timeline of resource requests: is the system safe? Draw a resource-allocation graph and watch cycles and the detection algorithm."},
  {"id":"m:pl.os-memory","title":"Memory, paging and virtual memory","text":"Memory, paging and virtual memory. Explain paging, the TLB and page faults. Run LRU by hand and say why it is popular. Explain thrashing. Paging with a TLB, multilevel page tables and segmentation: logical to physical, bit by bit. FIFO, LRU, Optimal, LFU, MFU, the clock and NRU, frame by frame, plus working sets and Belady's anomaly. First, next, best and worst fit on a live memory bar, plus buddy-system splits and merges."},
  {"id":"m:pl.db-design","title":"Keys, ER models and normalisation","text":"Keys, ER models and normalisation. Explain primary, candidate and foreign keys. Normalise a table to 3NF and BCNF and say what each form prevents. Closures, candidate keys, 1NF to BCNF, minimal cover and decompositions. Draw an ER diagram in Chen notation, then map it to tables one rule at a time, with every key shown."},
  {"id":"m:pl.db-txn","title":"Transactions, ACID and concurrency","text":"Transactions, ACID and concurrency. Explain each ACID property with an example of it failing. Describe dirty reads, lost updates and how locking prevents them. Precedence graphs, conflict and view serialisability, recoverable and strict schedules. Two-phase locking with a lock table and deadlocks, timestamp ordering and validation, step by step. Crash anywhere in the log, then watch redo repeat history and undo roll back the losers."},
  {"id":"m:pl.db-index","title":"Indexing","text":"Indexing. Explain why B+ trees suit disks and when an index hurts. Compare a hash index with a B+ tree index. Insert, delete and search with every split, borrow and merge animated. Keys in every node: median splits, predecessor and successor swaps, borrows and merges (CLRS t)."},
  {"id":"m:pl.cn-layers","title":"OSI and TCP/IP layers","text":"OSI and TCP/IP layers. Name each layer, its unit and a protocol at it. Explain encapsulation and what a router or switch looks at. A message going down the stack gaining headers, through a router that opens three layers, and back up, with every byte of overhead counted."},
  {"id":"m:pl.cn-transport","title":"TCP, UDP and congestion control","text":"TCP, UDP and congestion control. Walk through the three-way handshake and connection close. Compare TCP and UDP and pick one for a given app. Explain slow start and congestion avoidance. Slow start, Tahoe, Reno and CUBIC round by round, plus the three-way handshake and teardown. Stop-and-Wait, Go-Back-N and Selective Repeat on a timeline, with lost frames and ACKs."},
  {"id":"m:pl.cn-ip","title":"IP addressing and subnets","text":"IP addressing and subnets. Work out network, broadcast and host range from a CIDR prefix. Explain NAT and private address ranges. Network, broadcast and host range from any IPv4 address, in binary, plus a VLSM planner. Forward a packet by longest prefix match, bit by bit, and summarise routes into supernets."},
  {"id":"m:pl.sql-joins","title":"Joins","text":"Joins. Predict the rows from inner, left, right and full outer joins, including NULLs. Write a self join and an anti join. INNER, OUTER, SEMI and ANTI joins row by row, plus nested-loop, block nested-loop, sort-merge and hash join with I/O costs."},
  {"id":"m:stoc.dfa","title":"DFAs","text":"DFAs. Design a DFA for a described language. Trace a string through a DFA. Run a DFA, NFA or ε-NFA on any string and watch the active states light up."},
  {"id":"m:stoc.nfa","title":"NFAs and subset construction","text":"NFAs and subset construction. Convert an NFA with ε-moves to a DFA. The subset construction with ε-closures, the DFA growing one move at a time."},
  {"id":"m:stoc.minimise","title":"DFA minimisation","text":"DFA minimisation. Minimise a DFA by partition refinement. Partition refinement: 0-, 1-, 2-equivalence until equivalent states merge."},
  {"id":"m:stoc.cfg","title":"Context-free grammars","text":"Context-free grammars. Convert a grammar to Chomsky normal form. Check membership with CYK. Chomsky normal form step by step (ε, unit and useless rules, binarise), then on to Greibach normal form. Fill the CYK triangle cell by cell and get the parse tree for CNF grammars."},
  {"id":"m:stoc.pda","title":"Pushdown automata","text":"Pushdown automata. Design a PDA for a context-free language and trace it. Nondeterministic PDAs searched breadth first, the stack animated, and CFG → PDA."},
  {"id":"m:scd.ir","title":"Intermediate code","text":"Intermediate code. Write three-address code, quadruples and triples for an expression. Build the DAG of a basic block. Syntax tree to TAC, DAG with common subexpressions, quadruples and triples."},
  {"id":"m:scd.opt","title":"Optimisation and register allocation","text":"Optimisation and register allocation. Apply common subexpression elimination, constant folding and dead-code removal. Colour an interference graph to allocate registers. Leaders, basic blocks and the flow graph, then folding, propagation, CSE and dead code, one rewrite at a time. Liveness to a fixed point, the interference graph, then Chaitin's simplify, spill and select with k registers."},
  {"id":"m:ai.tokenisation","title":"Tokenisation","text":"Tokenisation. Train byte-pair encoding by hand on a small corpus and list its merges. Explain why some languages and code cost more tokens than English. Compare character, word and subword tokenisers on vocabulary size and unknown words. Train byte-pair encoding merge by merge on your own text, then see English, Hindi, code and numbers split into tokens."},
  {"id":"m:ai.embeddings","title":"Embeddings and similarity","text":"Embeddings and similarity. Compute cosine similarity, dot product and Euclidean distance and say when they disagree. Find nearest neighbours and solve a vector analogy. Explain what PCA keeps and loses when vectors are drawn in 2D. Hand-made word vectors you can read: cosine vs dot product vs distance, neighbours, analogies and semantic search, plotted with PCA."},
  {"id":"m:ai.attention","title":"Attention","text":"Attention. Compute one row of scaled dot-product attention by hand. Explain the causal mask and why scores are divided by √d. Describe what multiple heads add. Scaled dot-product attention by hand: Q·Kᵀ, scaling, the causal mask, softmax row by row and two heads, as a heatmap."},
  {"id":"m:ai.sampling","title":"Decoding and sampling","text":"Decoding and sampling. Apply temperature, top-k and top-p to a set of logits. Work out which tokens survive a top-p cut-off. Explain greedy decoding, repetition penalties and entropy. Next-token logits through temperature, top-k, top-p and repetition penalty, then a seeded draw, with entropy."},
  {"id":"m:ai.kv-cache","title":"Inference: prefill, decode and the KV cache","text":"Inference: prefill, decode and the KV cache. Work out KV cache memory from a model's shape. Explain why time to first token and tokens per second have different limits. Say how grouped-query attention shrinks the cache. Prefill vs decode step by step: what the KV cache saves, how its memory grows, time to first token and tokens per second."},
  {"id":"m:ai.search","title":"Keyword, dense and hybrid search","text":"Keyword, dense and hybrid search. Score documents with BM25 by hand, including idf and length normalisation. Rank by embedding similarity and say when it beats keywords. Fuse rankings with Reciprocal Rank Fusion and rerank the top results. BM25 by hand, dense search, hybrid with Reciprocal Rank Fusion, reranking, chunking strategies and the RAG prompt with citations."},
  {"id":"m:ai.rag","title":"Chunking and RAG","text":"Chunking and RAG. Compare fixed, overlapping, sentence and heading chunking on one document. Assemble a RAG prompt with numbered sources and ask for citations. Explain why an answer is only as good as what was retrieved. BM25 by hand, dense search, hybrid with Reciprocal Rank Fusion, reranking, chunking strategies and the RAG prompt with citations."},
  {"id":"m:ai.hnsw","title":"Vector indexes (HNSW)","text":"Vector indexes (HNSW). Explain how HNSW's layers make search fast. Trade recall for speed with M and ef. Measure recall@k against brute force. Build a layered small-world graph from random points, then watch a search hop down the layers, against brute force."},
  {"id":"t:sorting","title":"Sorting","text":"Sorting. Bubble, insertion, merge, quick, heap, radix and more, with pseudocode and live variables."},
  {"id":"t:binary-search-tree","title":"Binary search tree","text":"Binary search tree. Insert, delete (all three cases), search, successor and the four traversals, with nodes gliding."},
  {"id":"t:avl-tree","title":"AVL tree","text":"AVL tree. Balance factors on every node and LL, RR, LR and RL rotations animated as they happen."},
  {"id":"t:binary-heap","title":"Binary heap","text":"Binary heap. Min and max heaps as an array and a tree at once: sift up, sift down, build-heap, decrease-key."},
  {"id":"t:trie","title":"Trie","text":"Trie. Insert, search, prefix search, autocomplete and delete on a prefix tree that grows as you type."},
  {"id":"t:union-find","title":"Union-find","text":"Union-find. Disjoint sets with union by rank or size and path compression, compared with naive union."},
  {"id":"t:graph-traversal","title":"Graph traversal","text":"Graph traversal. BFS and DFS with the queue, stack and edge types, plus components, cycles, bipartite check and topological sort."},
  {"id":"t:minimum-spanning-tree","title":"Minimum spanning tree","text":"Minimum spanning tree. Kruskal with a live union-find forest and Prim with its priority queue, edge by edge."},
  {"id":"t:shortest-paths","title":"Shortest paths","text":"Shortest paths. Dijkstra, Bellman–Ford and Floyd–Warshall: every relaxation, negative cycles and the path rebuilt."},
  {"id":"t:strongly-connected-components","title":"Strongly connected components","text":"Strongly connected components. Kosaraju's two passes on G and its reverse, Tarjan's disc/low stack, and the condensation DAG."},
  {"id":"t:searching","title":"Searching","text":"Searching. Linear, binary, jump and interpolation search, plus lower and upper bound, probe by probe."},
  {"id":"t:stacks-queues","title":"Stacks & queues","text":"Stacks & queues. Push, pop, circular queues and deques, bracket matching, infix to postfix and postfix evaluation."},
  {"id":"t:linked-list","title":"Linked lists","text":"Linked lists. Singly, doubly and circular lists: insert, delete, reverse with moving arrows, and Floyd's cycle detection."},
  {"id":"t:dynamic-programming","title":"Dynamic programming","text":"Dynamic programming. DP tables filled cell by cell with traceback: LCS, edit distance, knapsack, coin change, matrix chain, LIS."},
  {"id":"t:cpu-scheduling","title":"CPU scheduling","text":"CPU scheduling. FCFS, SJF, SRTF, HRRN, Priority, Round Robin, multilevel and feedback queues, with a live Gantt chart."},
  {"id":"t:page-replacement","title":"Page replacement","text":"Page replacement. FIFO, LRU, Optimal, LFU, MFU, the clock and NRU, frame by frame, plus working sets and Belady's anomaly."},
  {"id":"t:disk-scheduling","title":"Disk scheduling","text":"Disk scheduling. FCFS, SSTF, SCAN, C-SCAN, LOOK, C-LOOK, N-step SCAN and F-SCAN, with the head's path drawn out."},
  {"id":"t:bankers-algorithm","title":"Banker's algorithm","text":"Banker's algorithm. Need matrix, safety check and a timeline of resource requests: is the system safe?"},
  {"id":"t:deadlock-detection","title":"Deadlock detection","text":"Deadlock detection. Draw a resource-allocation graph and watch cycles and the detection algorithm."},
  {"id":"t:semaphores","title":"Semaphores & synchronisation","text":"Semaphores & synchronisation. Producer–consumer, readers–writers, dining philosophers and race conditions. You pick who runs."},
  {"id":"t:memory-allocation","title":"Memory allocation","text":"Memory allocation. First, next, best and worst fit on a live memory bar, plus buddy-system splits and merges."},
  {"id":"t:address-translation","title":"Address translation","text":"Address translation. Paging with a TLB, multilevel page tables and segmentation: logical to physical, bit by bit."},
  {"id":"t:file-systems","title":"File systems and inodes","text":"File systems and inodes. Inode direct and indirect pointers: maximum file size, and the disk reads to reach any byte. Plus contiguous, linked and indexed allocation."},
  {"id":"t:b-plus-tree","title":"B+ tree","text":"B+ tree. Insert, delete and search with every split, borrow and merge animated."},
  {"id":"t:b-tree","title":"B-tree","text":"B-tree. Keys in every node: median splits, predecessor and successor swaps, borrows and merges (CLRS t)."},
  {"id":"t:normalization","title":"Normalisation","text":"Normalisation. Closures, candidate keys, 1NF to BCNF, minimal cover and decompositions."},
  {"id":"t:sql-joins","title":"SQL joins","text":"SQL joins. INNER, OUTER, SEMI and ANTI joins row by row, plus nested-loop, block nested-loop, sort-merge and hash join with I/O costs."},
  {"id":"t:query-processing","title":"Query processing","text":"Query processing. SQL to relational algebra trees, rewritten step by step: push selections down, reorder joins, estimate sizes."},
  {"id":"t:serializability","title":"Serialisability","text":"Serialisability. Precedence graphs, conflict and view serialisability, recoverable and strict schedules."},
  {"id":"t:concurrency-control","title":"Concurrency control","text":"Concurrency control. Two-phase locking with a lock table and deadlocks, timestamp ordering and validation, step by step."},
  {"id":"t:recovery","title":"Log-based recovery","text":"Log-based recovery. Crash anywhere in the log, then watch redo repeat history and undo roll back the losers."},
  {"id":"t:hashing","title":"Hashing & indexing","text":"Hashing & indexing. Chaining, linear, quadratic and double hashing, plus extendible hashing."},
  {"id":"t:er-to-relational","title":"ER to relational","text":"ER to relational. Draw an ER diagram in Chen notation, then map it to tables one rule at a time, with every key shown."},
  {"id":"t:subnetting","title":"Subnetting & VLSM","text":"Subnetting & VLSM. Network, broadcast and host range from any IPv4 address, in binary, plus a VLSM planner."},
  {"id":"t:sliding-window","title":"Sliding window protocols","text":"Sliding window protocols. Stop-and-Wait, Go-Back-N and Selective Repeat on a timeline, with lost frames and ACKs."},
  {"id":"t:routing","title":"Routing algorithms","text":"Routing algorithms. LSP flooding, Dijkstra and distance-vector routing, with packets hopping along the chosen path."},
  {"id":"t:tcp-congestion-control","title":"TCP congestion control","text":"TCP congestion control. Slow start, Tahoe, Reno and CUBIC round by round, plus the three-way handshake and teardown."},
  {"id":"t:error-detection","title":"Error detection & correction","text":"Error detection & correction. CRC long division, Hamming codes that fix a flipped bit, and the Internet checksum."},
  {"id":"t:ip-fragmentation","title":"IP fragmentation","text":"IP fragmentation. Split a datagram for a smaller MTU: fragment sizes, offsets and the MF flag."},
  {"id":"t:cidr-and-longest-prefix-match","title":"CIDR & longest prefix match","text":"CIDR & longest prefix match. Forward a packet by longest prefix match, bit by bit, and summarise routes into supernets."},
  {"id":"t:mac-protocols","title":"MAC protocols","text":"MAC protocols. Pure and slotted ALOHA, CSMA/CD with binary exponential backoff, and CSMA/CA with RTS/CTS."},
  {"id":"t:traffic-shaping","title":"Traffic shaping","text":"Traffic shaping. Leaky and token buckets filling and draining tick by tick, plus the burst-length formula."},
  {"id":"t:dns-and-http","title":"DNS & HTTP","text":"DNS & HTTP. Iterative and recursive DNS lookups with caching, and HTTP page-load times for every connection type."},
  {"id":"t:osi-encapsulation","title":"OSI & TCP/IP encapsulation","text":"OSI & TCP/IP encapsulation. A message going down the stack gaining headers, through a router that opens three layers, and back up, with every byte of overhead counted."},
  {"id":"t:finite-automata","title":"Finite automata","text":"Finite automata. Run a DFA, NFA or ε-NFA on any string and watch the active states light up."},
  {"id":"t:nfa-to-dfa","title":"NFA to DFA","text":"NFA to DFA. The subset construction with ε-closures, the DFA growing one move at a time."},
  {"id":"t:dfa-minimization","title":"DFA minimisation","text":"DFA minimisation. Partition refinement: 0-, 1-, 2-equivalence until equivalent states merge."},
  {"id":"t:regex-to-nfa","title":"Regex to NFA","text":"Regex to NFA. Thompson's construction, fragment by fragment, for any regular expression."},
  {"id":"t:dfa-to-regex","title":"DFA to regex & product","text":"DFA to regex & product. State elimination with edge labels rerouting as states vanish, plus union and intersection of DFAs."},
  {"id":"t:pumping-lemma","title":"Pumping lemma","text":"Pumping lemma. Play the pumping game against an adversary: pick s, it splits xyz, you pick i. Can you prove L isn't regular?"},
  {"id":"t:pushdown-automata","title":"Pushdown automata","text":"Pushdown automata. Nondeterministic PDAs searched breadth first, the stack animated, and CFG → PDA."},
  {"id":"t:cfg-to-cnf","title":"CFG to CNF and GNF","text":"CFG to CNF and GNF. Chomsky normal form step by step (ε, unit and useless rules, binarise), then on to Greibach normal form."},
  {"id":"t:cyk-parsing","title":"CYK parsing","text":"CYK parsing. Fill the CYK triangle cell by cell and get the parse tree for CNF grammars."},
  {"id":"t:turing-machine","title":"Turing machine","text":"Turing machine. A live tape and head: aⁿbⁿcⁿ, palindromes, binary increment, busy beaver."},
  {"id":"t:lexical-analysis","title":"Lexical analysis","text":"Lexical analysis. A maximal-munch lexer DFA turns characters into tokens and fills the symbol table."},
  {"id":"t:left-recursion","title":"Left recursion & factoring","text":"Left recursion & factoring. Remove direct and indirect left recursion, then left factor, rule by rule."},
  {"id":"t:first-follow","title":"FIRST & FOLLOW","text":"FIRST & FOLLOW. Compute FIRST and FOLLOW sets pass by pass, with the reason for every symbol."},
  {"id":"t:ll1-parsing","title":"LL(1) parsing","text":"LL(1) parsing. Predictive parsing table, conflicts, and a stack trace that grows the parse tree."},
  {"id":"t:operator-precedence","title":"Operator-precedence parsing","text":"Operator-precedence parsing. LEADING and TRAILING, the ⋖ ≐ ⋗ table, precedence functions and shift-reduce parses."},
  {"id":"t:lr-parsing","title":"LR parsing","text":"LR parsing. LR(0), SLR, LALR and CLR: item sets, tables, conflicts and bottom-up parses."},
  {"id":"t:syntax-directed-translation","title":"Syntax-directed translation","text":"Syntax-directed translation. Annotated parse trees: synthesised and inherited attributes evaluated in dependency order."},
  {"id":"t:three-address-code","title":"Three-address code & DAG","text":"Three-address code & DAG. Syntax tree to TAC, DAG with common subexpressions, quadruples and triples."},
  {"id":"t:code-optimisation","title":"Code optimisation","text":"Code optimisation. Leaders, basic blocks and the flow graph, then folding, propagation, CSE and dead code, one rewrite at a time."},
  {"id":"t:register-allocation","title":"Register allocation","text":"Register allocation. Liveness to a fixed point, the interference graph, then Chaitin's simplify, spill and select with k registers."},
  {"id":"t:number-systems","title":"Number systems","text":"Number systems. Base conversion with every division and multiplication, fractions included, plus 1's and 2's complement and overflow."},
  {"id":"t:k-map","title":"K-map minimiser","text":"K-map minimiser. Karnaugh maps for 2 to 5 variables with don't-cares: prime implicants, essential ones, minimal SOP and POS, and Quine-McCluskey."},
  {"id":"t:combinational-circuits","title":"Combinational circuits","text":"Combinational circuits. Multiplexers, decoders, half and full adders, ripple-carry delay and comparators, with live values on every wire."},
  {"id":"t:sequential-circuits","title":"Sequential circuits","text":"Sequential circuits. SR, JK, D and T flip-flops with timing diagrams, conversions, synchronous and ripple counters, ring and Johnson counters."},
  {"id":"t:cache-mapping","title":"Cache mapping","text":"Cache mapping. Tag, index and offset bits, then a reference trace with every hit, miss and LRU or FIFO eviction, plus average access time."},
  {"id":"t:pipelining","title":"Pipelining","text":"Pipelining. A 5-stage timing diagram cycle by cycle: data hazards, forwarding, load-use stalls, branch penalties, CPI and speedup."},
  {"id":"t:addressing-modes","title":"Addressing modes","text":"Addressing modes. Immediate, direct, indirect, register, indexed, base, relative and auto-increment, on a small machine; plus instruction formats."},
  {"id":"t:ieee-754","title":"IEEE 754 floating point","text":"IEEE 754 floating point. Encode and decode half, single and double precision: normalise, bias, round to nearest even, denormals, ∞ and NaN."},
  {"id":"t:io-dma","title":"I/O, interrupts and DMA","text":"I/O, interrupts and DMA. Polling, interrupts and DMA compared by CPU time, worked out step by step, plus burst and cycle-stealing DMA."},
  {"id":"t:propositional-logic","title":"Propositional logic","text":"Propositional logic. Truth tables built column by column, equivalences, CNF and DNF, rules of inference and quantifiers over a small domain."},
  {"id":"t:sets-relations","title":"Sets and relations","text":"Sets and relations. A relation as a matrix and a digraph: properties, Warshall's closure, equivalence classes, Hasse diagrams and lattices."},
  {"id":"t:combinatorics","title":"Combinatorics","text":"Combinatorics. Permutations, combinations, stars and bars, inclusion-exclusion on a Venn diagram, derangements, Catalan numbers and recurrences."},
  {"id":"t:graph-theory","title":"Graph theory","text":"Graph theory. Havel-Hakimi, Euler and Hamilton tours, bipartite checks, chromatic number, matchings, Euler's formula and spanning-tree counts."},
  {"id":"t:recurrences","title":"Recurrences","text":"Recurrences. Recursion trees drawn level by level, master theorem cases with the reasoning, substitution checks and growth rates compared."},
  {"id":"t:matrices","title":"Matrices","text":"Matrices. Gaussian elimination with exact fractions: rank, determinants, inverses, Ax = b, and eigenvalues with eigenvectors."},
  {"id":"t:probability","title":"Probability","text":"Probability. Sample spaces, conditional probability and Bayes with a tree, E[X] and Var(X), and binomial to normal distributions plotted."},
  {"id":"t:calculus","title":"Calculus","text":"Calculus. Limits by table and L'Hôpital, maxima and minima with a sign chart, Riemann sums closing in on an integral, and the MVT."},
  {"id":"t:aptitude","title":"Quantitative aptitude","text":"Quantitative aptitude. Percentages, profit, mixtures, work, speed, averages, interest, series, clocks and calendars, solved step by step, then timed sets."},
  {"id":"t:tokenisation","title":"Tokenisation (BPE)","text":"Tokenisation (BPE). Train byte-pair encoding merge by merge on your own text, then see English, Hindi, code and numbers split into tokens."},
  {"id":"t:embeddings","title":"Embeddings","text":"Embeddings. Hand-made word vectors you can read: cosine vs dot product vs distance, neighbours, analogies and semantic search, plotted with PCA."},
  {"id":"t:attention","title":"Attention","text":"Attention. Scaled dot-product attention by hand: Q·Kᵀ, scaling, the causal mask, softmax row by row and two heads, as a heatmap."},
  {"id":"t:sampling","title":"Sampling","text":"Sampling. Next-token logits through temperature, top-k, top-p and repetition penalty, then a seeded draw, with entropy."},
  {"id":"t:kv-cache","title":"KV cache","text":"KV cache. Prefill vs decode step by step: what the KV cache saves, how its memory grows, time to first token and tokens per second."},
  {"id":"t:retrieval","title":"Retrieval and RAG","text":"Retrieval and RAG. BM25 by hand, dense search, hybrid with Reciprocal Rank Fusion, reranking, chunking strategies and the RAG prompt with citations."},
  {"id":"t:hnsw","title":"HNSW vector search","text":"HNSW vector search. Build a layered small-world graph from random points, then watch a search hop down the layers, against brute force."}];
